-- 授权：管理员角色全量（admin / superadmin 语义即管理员，应持有全部写码，
-- 否则新补码会让管理员在页面上看不到写按钮，属"误锁管理员"）
INSERT INTO public.core_role_permissions (role_id, permission_id, created_at)
SELECT r.id, p.id, now()
FROM public.core_roles r
JOIN public.core_permissions p ON p.description LIKE '[batch16]%'
WHERE r.name IN ('admin', 'superadmin')
  AND NOT EXISTS (
    SELECT 1 FROM public.core_role_permissions x
     WHERE x.role_id = r.id AND x.permission_id = p.id
);

-- 授权：域经理角色（幂等）
INSERT INTO public.core_role_permissions (role_id, permission_id, created_at)
SELECT r.id, p.id, now()
FROM (VALUES
    ('erp','erp_manager'),
    ('hrm','hrm_manager'),
    ('qms','qms_manager'),
    ('iam','admin')
) AS m(module, role_name)
JOIN public.core_roles r ON r.name = m.role_name
JOIN public.core_permissions p
  ON p.code LIKE m.module || ':%'
 AND p.code ~ ':(create|update|delete)$'
 AND p.description LIKE '[batch16]%'
WHERE NOT EXISTS (
    SELECT 1 FROM public.core_role_permissions x
     WHERE x.role_id = r.id AND x.permission_id = p.id
);
